          <main class="rooms-grid">${this.areas.map(h=>v`<a class="room glass" href=${this.route(`area-${h.id}`)}><span class="room-icon">${N("rooms",25)}</span><span class="room-arrow">${N("arrow",20)}</span><div><h3>${h.name}</h3><p>${c("{n} équipement|{n} équipements",{n:h.deviceCount})} · ${c("{n} lumière|{n} lumières",{n:h.lightCount})}</p></div></a>`)}${this.inventory?v`<a class="room glass" href=${this.route("inventory")}><span class="room-icon">${N("scan",25)}</span><span class="room-arrow">${N("arrow",20)}</span><div><h3>${this.inventory.title}</h3><p>${c("{n} entité sans carte dédiée|{n} entités sans carte dédiée",{n:this.inventory.count})}</p></div></a>`:E}</main>
